REPLACE INTO `clob_datatype_storage` (`uuid`,`value`) VALUES ('dcec3f1b-3166-11f0-b8e6-0a0027000011','{\r\n    \"name\": \"A -Risk Stratification Adult\",\r\n    \"description\": \"Risk Stratification Adult\",\r\n    \"version\": \"1.0\",\r\n    \"published\": false,\r\n    \"retired\": false,\r\n    \"processor\": \"EncounterFormProcessor\",\r\n    \"encounterType\": \"a8939d83-59d7-4f3c-aa80-029d7e4d8095\",\r\n    \"referencedForms\": [],\r\n    \"uuid\": \"c50f3dda-754b-4fc5-9af9-0df15527b9e9\",\r\n    \"pages\": [\r\n        {\r\n            \"label\": \"Adult Risk Stratification\",\r\n            \"sections\": [\r\n                {\r\n                    \"label\": \"I\'m going to ask you some questions to better understand your HIV risk. These can be very personal questions and may be hard to answer. In order to accurately understand your risk for HIV, I need to ask these questions and I need you to answer them as honestly as possible. If you need a moment to think before answering that is fine. Whatever we discuss will remain confidential. Note: When using the tool, if someone reports never having an HIV test remove \'since your last HIV test\' from the beginning of the question.\",\r\n                    \"questions\": [\r\n                        {\r\n                            \"label\": \"Date of Assessment\",\r\n                            \"id\": \"Date_of_Assessment\",\r\n                            \"require\": true,\r\n                            \"questionOptions\": {\r\n                                \"rendering\": \"date\",\r\n                                \"concept\": \"6bcaf85b-8504-4c7f-b510-a50436236b80\"\r\n                            },\r\n                            \"type\": \"encounterDateTime\",\r\n                            \"validators\": [\r\n                                {\r\n                                    \"type\": \"date\",\r\n                                    \"allowFutureDates\": \"false\"\r\n                                }\r\n                            ]\r\n                        },\r\n                        {\r\n                            \"label\": \"Is this HIV test based on a Clinician/Doctor/Health Care Provider\'s request? \",\r\n                            \"id\": \"Is_this_HIV_test_based_on_a_Clinician\",\r\n                            \"required\": true,\r\n                            \"questionOptions\": {\r\n                                \"rendering\": \"select\",\r\n                                \"concept\": \"46320a3c-72cf-48b6-ad32-a4ce6912de91\",\r\n                                \"answers\": [\r\n                                    {\r\n                                        \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                                        \"label\": \"Yes\"\r\n                                    },\r\n                                    {\r\n                                        \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                                        \"label\": \"No\"\r\n                                    }\r\n                                ]\r\n                            },\r\n                            \"type\": \"obs\"\r\n                        },\r\n                        {\r\n                            \"label\": \"When was your most recent HIV test done? Approximate date of (or months/years/weeks since) last HIV test?\",\r\n                            \"id\": \"When_was_your_last_HIV_test_done\",\r\n                            \"required\": true,\r\n                            \"questionOptions\": {\r\n                                \"rendering\": \"date\",\r\n                                \"concept\": \"164400AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"\r\n                            },\r\n                            \"type\": \"obs\",\r\n                            \"validators\": [\r\n                                {\r\n                                    \"type\": \"date\",\r\n                                    \"allowFutureDates\": \"false\"\r\n                                }\r\n                            ]\r\n                        },\r\n                        {\r\n                            \"label\": \"What was the result?\",\r\n                            \"id\": \"What_was_the_result\",\r\n                            \"required\": true,\r\n                            \"questionOptions\": {\r\n                                \"rendering\": \"select\",\r\n                                \"concept\": \"6c4ebfeb-f613-493a-993a-ff5efa012e6d\",\r\n                                \"answers\": [\r\n                                    {\r\n                                        \"concept\": \"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                                        \"label\": \"Positive\"\r\n                                    },\r\n                                    {\r\n                                        \"concept\": \"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                                        \"label\": \"Negative\"\r\n                                    },\r\n                                    {\r\n                                        \"concept\": \"159451AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                                        \"label\": \"Never\"\r\n                                    },\r\n                                    {\r\n                                        \"concept\": \"1067AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\r\n                                        \"label\": \"Unknown\"\r\n                                    }\r\n                                ]\r\n                            },\r\n                            \"type\": \"obs\"\r\n                        },\r\n                        {\r\n                            \"label\": \"Since your last HIV test, have you had anal or vaginal or oral sex without a condom with someone who was HIV positive or unaware of their HIV status?\",\r\n